// CurrencyPopover.js
import { useState } from "react";
import { MenuItem, Stack, Box, Chip } from "@mui/material";
import MenuPopover from "src/components/MenuPopover";
import { IconButtonAnimate } from "src/components/animate";
import useCurrencyCurrent from "src/contexts/CurrencyContext";

export default function CurrencyPopover() {
  const { allCurrency, currentCurrency, onChangeCurrency } =
    useCurrencyCurrent();
  const [open, setOpen] = useState(null);

  const handleOpen = (e) => setOpen(e.currentTarget);
  const handleClose = () => setOpen(null);

  return (
    <>
      <IconButtonAnimate
        onClick={handleOpen}
        sx={{
          height: 40,
          px: 1,
          ...(open && { bgcolor: "action.selected" }),
        }}
      >
        <Stack direction="row" spacing={1} alignItems="center">
          <Box
            component="span"
            aria-label={currentCurrency.label}
            sx={{ fontSize: 20, lineHeight: 1 }}
          >
            {currentCurrency.icon}
          </Box>
          <Chip
            size="small"
            label={currentCurrency.value}
            variant="outlined"
            sx={{ height: 22, fontWeight: 700 }}
          />
        </Stack>
      </IconButtonAnimate>

      <MenuPopover
        open={Boolean(open)}
        anchorEl={open}
        onClose={handleClose}
        sx={{
          mt: 1.5,
          ml: 0.75,
          width: 110,
          "& .MuiMenuItem-root": {
            px: 1,
            typography: "body2",
            borderRadius: 0.75,
          },
        }}
      >
        <Stack spacing={0.75}>
          {allCurrency.map((opt) => (
            <MenuItem
              key={opt.value}
              selected={opt.value === currentCurrency.value}
              onClick={() => {
                onChangeCurrency(opt.value);
                handleClose();
                window.location.reload();
              }}
            >
              <Box
                component="span"
                sx={{ fontSize: 20, mr: 1.25, lineHeight: 1 }}
              >
                {opt.icon}
              </Box>

              <Chip
                size="small"
                label={opt.value}
                sx={{ mr: 1, height: 22, fontWeight: 700 }}
              />
            </MenuItem>
          ))}
        </Stack>
      </MenuPopover>
    </>
  );
}
