const extractErrorMessage = (error) => {
  if (error.response?.data) {
    const { data } = error.response;

    if (typeof data === "string") {
      // Si le message est directement une chaîne, utilisez-le comme message d'erreur
      return data;
    } else if (Array.isArray(data)) {
      // Si le message est un tableau, utilisez sa première entrée comme message d'erreur
      return data[0];
    } else if (Array.isArray(data.non_field_errors) && data.non_field_errors.length) {
      return data.non_field_errors[0];
    } else if (data.detail) {
      // Si la clé 'detail' est présente, utilisez sa valeur comme message d'erreur
      return data.detail;
    }
  }

  // Utilisez un message générique si aucune correspondance n'est trouvée
  return "An error occurred. Please try again.";
};

export default extractErrorMessage;
